"use client";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect,useRef,useState } from "react";
import type { MatchPage } from "@/server/matching";
import type { CandidateSummary } from "@/domain/matching";
import { activeDecision, workflowSteps, type WorkflowDTO, type WorkflowCommand, type WorkflowList } from "@/domain/workflow";
import type { ProfileDetail } from "@/domain/types";
import { api } from "./api";
import { Badge,Button,EmptyState,SectionHeader } from "./ui";
import { Tabs } from "./tabs";
import { Dialog } from "./dialog";
import { LivePortrait } from "./profiles-live";
import { PairBreakdown } from "./matches-live";
import { WorkflowPreview } from "./workflow";
type Candidates=Omit<MatchPage,"results">&{results:(MatchPage["results"][number]&{assessmentStamp:string})[]};
type WithoutRevision<T>=T extends unknown?Omit<T,"revision">:never;
type CommandInput=WithoutRevision<WorkflowCommand>;
const statusLabels={IN_PROGRESS:"In progress",MATCH_APPROVED:"Match approved",MATCH_REJECTED:"Match rejected",REVIEW_REQUIRED:"Review required",ARCHIVED:"Archived"};
function Person({profile}:{profile:CandidateSummary}){return <div className="workflow-summary"><LivePortrait profile={profile}/><div><h3>{profile.displayName}{profile.reportedAge!==null?", "+profile.reportedAge:""}</h3><p className="muted small">{profile.city??"City unknown"}</p><Badge tone={profile.kind==="DEMO"?"warning":"neutral"}>{profile.kind}</Badge></div></div>;}
export function WorkflowLive({initial,list,sources,truncated}:{initial:WorkflowDTO|null;list:WorkflowList;sources:CandidateSummary[];truncated:boolean}){
  const router=useRouter();
  const [workflow,setWorkflow]=useState(initial),[sourceId,setSourceId]=useState(initial?.source.id??sources[0]?.id??"");
  const [candidates,setCandidates]=useState<Candidates|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(""),[message,setMessage]=useState("");
  const [confirmation,setConfirmation]=useState<"approve"|"reject"|"reopen"|"archive"|null>(null),[reviewChecked,setReviewChecked]=useState(false);
  const feedback=useRef<HTMLParagraphElement>(null),focusFeedback=useRef(false);
  useEffect(()=>{if(message&&focusFeedback.current){feedback.current?.focus({preventScroll:true});focusFeedback.current=false;}},[message,workflow?.revision]);
  const step=workflow?.stale?Math.min(workflow.currentStep,3):workflow?.currentStep??1;
  const approved=workflow?.status==="MATCH_APPROVED"&&!workflow.stale,readOnly=workflow?.status==="ARCHIVED",locked=!!workflow&&activeDecision(workflow);
  async function reload(){if(!workflow)return;setBusy(true);setError("");try{setWorkflow(await api<WorkflowDTO>("/api/workspace/workflows/"+workflow.id));setReviewChecked(false);setCandidates(null);setMessage("Current workflow loaded.");}catch(e){setError(e instanceof Error?e.message:"Unable to reload.");}finally{setBusy(false);}}
  async function command(input:CommandInput){
    if(!workflow)return;setBusy(true);setError("");setMessage("");
    try{
      const result=await api<WorkflowDTO>("/api/workspace/workflows/"+workflow.id,"PATCH",{...input,revision:workflow.revision});
      focusFeedback.current=input.action!=="navigate";setWorkflow(result);setCandidates(null);setReviewChecked(false);setConfirmation(null);
      setMessage(input.action==="approve"?"Human approval saved. Local email drafting is available; email approval is separate.":input.action==="reject"?"Rejection saved. Draft previews are locked.":input.action==="reopen"?"Decision reopened. Refresh and review new evidence before deciding.":input.action==="review"?"Review saved for this exact assessment.":"Workflow saved.");router.refresh();
    }catch(e){setError(e instanceof Error?e.message:"Unable to save workflow.");setConfirmation(null);setReviewChecked(false);try{setWorkflow(await api<WorkflowDTO>("/api/workspace/workflows/"+workflow.id));}catch{/* Keep the last confirmed state and visible error. */}}
    finally{setBusy(false);}
  }
  async function selectSource(){
    setBusy(true);setError("");setMessage("");
    try{const profile=await api<ProfileDetail>("/api/workspace/profiles/"+sourceId);
      if(workflow){await command({action:"source",sourceId,sourceRevision:profile.revision});return;}
      const created=await api<WorkflowDTO>("/api/workspace/workflows","POST",{sourceId,sourceRevision:profile.revision});setWorkflow(created);router.push("/workflow?id="+created.id);
    }catch(e){setError(e instanceof Error?e.message:"Unable to select this source.");}finally{setBusy(false);}
  }
  async function loadCandidates(){if(!workflow)return;setBusy(true);setError("");try{setCandidates(await api<Candidates>("/api/workspace/workflows/"+workflow.id+"/candidates","POST",{}));}catch(e){setCandidates(null);setError(e instanceof Error?e.message:"Unable to rank candidates.");}finally{setBusy(false);}}
  function navigate(next:number){if(workflow&&!busy&&next!==step)void command({action:"navigate",step:next});}
  function confirm(){
    if(!confirmation||!workflow)return;
    if(confirmation==="approve"||confirmation==="reject")void command({action:confirmation,snapshotId:workflow.snapshotId!,confirmation:confirmation==="approve"?"APPROVE MATCH":"REJECT MATCH"} as CommandInput);
    else void command({action:confirmation,confirmation:confirmation==="reopen"?"REOPEN MATCH":"ARCHIVE WORKFLOW"} as CommandInput);
  }
  const disabled=workflow?workflowSteps.map((_,i)=>!!readOnly||!!workflow.stale&&i>=2||i>=2&&!workflow.snapshot||i>=3&&!approved):[false,true,true,true,true];
  return <div className="workflow-live" aria-busy={busy}>
    <section className="panel panel-padding form-stack"><SectionHeader title="Saved workflows" description="One active workflow per source. Archived journeys preserve their decision history." action={workflow?<Link className="button button-secondary" href="/workflow">Start another workflow</Link>:undefined}/>
      {list.workflows.length?<ul className="workflow-list">{list.workflows.map(w=><li key={w.id}><Link href={"/workflow?id="+w.id} aria-current={workflow?.id===w.id?"page":undefined}>{w.source.displayName}{w.candidate?" & "+w.candidate.displayName:""}</Link><span className="muted small">{statusLabels[w.status]} · step {w.currentStep}</span></li>)}</ul>:<p className="muted">No saved workflows yet. Select a source to begin.</p>}
      {list.nextPage&&<Link className="text-link" href={"/workflow?page="+list.nextPage}>More saved workflows →</Link>}
    </section>
    {busy&&<p role="status">Loading or saving the current workflow…</p>}{error&&<div className="panel panel-padding"><p role="alert" className="form-error">{error}</p><Button variant="secondary" disabled={busy||!workflow} onClick={reload}>Reload workflow</Button></div>}{message&&<p ref={feedback} role="status" tabIndex={-1}>{message}</p>}
    {workflow&&<><div className="workflow-context"><strong>Saved journey · step {step} of 5</strong><Badge tone={workflow.stale?"warning":approved?"success":"accent"}>{workflow.stale?"Review required":statusLabels[workflow.status]}</Badge></div><div className="workflow-pair"><Person profile={workflow.source}/>{workflow.candidate&&<Person profile={workflow.candidate}/>}</div><div className="button-row"><Button variant="secondary" disabled={busy} onClick={reload}>Check for changes</Button>{locked&&!readOnly&&<Button variant="secondary" disabled={busy} onClick={()=>setConfirmation("reopen")}>Reopen decision</Button>}{!readOnly&&<Button variant="ghost" disabled={busy} onClick={()=>setConfirmation("archive")}>Archive workflow</Button>}</div></>}
    {workflow?.stale&&<section className="panel panel-padding workflow-warning" role="alert"><h2>Assessment changed — review required</h2><p>Profiles, preferences, eligibility or scoring settings changed. The old snapshot is historical evidence. Its review and approval cannot unlock draft or delivery previews.</p><Button disabled={busy||locked||readOnly||!workflow.candidate} onClick={()=>command({action:"refresh"})}>Refresh assessment</Button>{locked&&<p className="small">Reopen the saved decision before refreshing.</p>}{!workflow.candidate&&<p className="small">Select the source again to update its revision.</p>}</section>}
    <Tabs labels={workflowSteps} label="Saved workflow steps" selected={step-1} disabled={disabled} onSelect={i=>navigate(i+1)}>
      {step===1&&<section className="panel panel-padding form-stack"><p className="eyebrow">STEP 01 · SELECT CUSTOMER</p><h2>Start with a person.</h2><label>Workflow source<select className="control" value={sourceId} disabled={busy||locked||readOnly} onChange={e=>setSourceId(e.target.value)}><option value="">Choose an active, approved profile</option>{sources.map(p=><option key={p.id} value={p.id}>{p.displayName} · {p.kind}</option>)}</select></label>{truncated&&<p className="muted small">The first 200 active, approved sources with current age confirmation are listed.</p>}<p className="muted small">An active, approved profile and a recently confirmed adult age are required. Changing source clears the candidate and review. Reopen any decision first.</p><Button disabled={busy||!sourceId||locked||readOnly} onClick={selectSource}>{workflow?"Save selected source":"Create workflow"}</Button>{!sources.length&&<Link href="/profiles/new" className="text-link">Create a profile →</Link>}</section>}
      {step===2&&workflow&&<section className="form-stack"><div className="panel panel-padding"><p className="eyebrow">STEP 02 · REVIEW MATCHES</p><h2>Review eligible candidates.</h2><p className="muted">Current deterministic ranking stays within {workflow.source.kind}. Unknown hard-rule evidence is excluded. Selecting a candidate saves a compact assessment; it makes no decision.</p><div className="button-row"><Button disabled={busy||readOnly||locked} onClick={()=>loadCandidates()}>Load current candidates</Button>{workflow.candidate&&!workflow.snapshot&&!locked&&<Button variant="secondary" disabled={busy||readOnly} onClick={()=>command({action:"refresh"})}>Refresh assessment</Button>}</div></div>{candidates&&<><p role="status">{candidates.total} eligible candidates · showing at most 10 · {candidates.excluded.unresolved} pairs need eligibility review</p>{candidates.results.length?<div className="match-grid">{candidates.results.map(r=><article className="match-card panel" key={r.candidate.id}><div className="match-photo"><LivePortrait profile={r.candidate}/></div><div className="match-card-copy"><h3>{r.candidate.displayName}, {r.candidate.reportedAge}</h3><p className="muted">{r.candidate.city??"City unknown"}</p><Badge>{r.candidate.kind}</Badge><p>Heuristic score: {r.assessment.overallScore??"Unknown"}/100 · {r.assessment.weightedCompleteness}% completeness</p><Button disabled={busy||locked||readOnly} onClick={()=>command({action:"candidate",candidateId:r.candidate.id,assessmentStamp:r.assessmentStamp})}>Select {r.candidate.displayName}</Button></div></article>)}</div>:<div className="panel"><EmptyState title="No eligible candidates" description="Review confirmed ages and both profiles’ strict preferences before continuing."/></div>}</>}</section>}
      {step===3&&workflow?.snapshot&&<><div className="panel panel-padding"><p className="eyebrow">STEP 03 · READ EXPLANATION</p><h2>Evidence before a decision.</h2><p>Heuristic score: <strong>{workflow.snapshot.assessment.overallScore??"Unknown"}/100</strong> · <strong>{workflow.snapshot.assessment.weightedCompleteness}% completeness</strong></p><p className="muted small">This indicator is not a probability of relationship success. Review the factor evidence, unknowns and versions before deciding.</p><p className="small">Assessment recorded {new Date(workflow.snapshot.createdAt).toLocaleString()}. Weight version {workflow.snapshot.assessment.weightVersion}; profile revisions {workflow.snapshot.assessment.sourceRevision}/{workflow.snapshot.assessment.candidateRevision}.</p></div><PairBreakdown key={workflow.snapshot.id} assessment={workflow.snapshot.assessment} sourceId={workflow.source.id} candidateId={workflow.candidate!.id}/><section className="panel panel-padding form-stack"><h2>Your judgment leads the way.</h2>{workflow.reviewedAt&&!workflow.stale?<p role="status">Explicit review recorded {new Date(workflow.reviewedAt).toLocaleString()} for this assessment.</p>:<><label className="workflow-review-check"><input type="checkbox" checked={reviewChecked} disabled={busy||locked||workflow.stale||readOnly} onChange={e=>setReviewChecked(e.target.checked)}/>I reviewed this assessment, its completeness, missing evidence and limitations.</label><Button disabled={busy||!reviewChecked||locked||workflow.stale||readOnly} onClick={()=>command({action:"review",snapshotId:workflow.snapshotId!,confirmation:"REVIEWED"})}>Record explanation review</Button></>}<p className="muted small">Review records your reading of this exact snapshot. Approval is a separate human decision to continue toward a future introduction. No email is authorized or sent.</p><div className="button-row"><Button disabled={busy||!workflow.reviewedAt||locked||workflow.stale||readOnly} onClick={()=>setConfirmation("approve")}>Approve Match</Button><Button variant="danger" disabled={busy||!workflow.reviewedAt||locked||workflow.stale||readOnly} onClick={()=>setConfirmation("reject")}>Reject Match</Button></div>{workflow.status==="MATCH_REJECTED"&&<p>Rejected match. Draft and delivery previews are locked until an explicit reopen and fresh review.</p>}</section></>}
      {step===4&&approved&&<section className="panel panel-padding form-stack"><p className="eyebrow">STEP 04</p><h2>Prepare an editable introduction</h2><Badge tone="success">Human match approval saved</Badge><p>Create a local plain-text draft for either member of this approved pair. Review the exact private recipient and outgoing message before separate email approval.</p><Link className="button button-primary" href={"/email?workflowId="+workflow!.id}>Open workflow email drafts</Link></section>}
      {step===5&&approved&&<section className="panel panel-padding form-stack"><p className="eyebrow">STEP 05</p><h2>Choose delivery with current evidence</h2><p>Copy or export draft text locally, or approve an exact outgoing email and separately confirm dispatch when Resend is configured. Match approval alone never sends. Delivery evidence remains in the email workspace.</p><Link className="button button-primary" href={"/email?workflowId="+workflow!.id}>Review email approval and delivery</Link></section>}
      {readOnly&&<p className="muted">Archived workflow. Its history remains available below.</p>}
    </Tabs>
    {workflow&&<><div className="workflow-navigation"><Button variant="secondary" disabled={busy||step===1||readOnly} onClick={()=>navigate(step-1)}>Previous step</Button><span className="muted small">Saved step {step} of 5</span><Button variant="secondary" disabled={busy||step===5||readOnly||workflow.stale&&step>=2||step===2&&!workflow.snapshot||step===3&&!approved} onClick={()=>navigate(step+1)}>{step===4?"Continue to delivery review":"Continue"}</Button></div><section className="panel panel-padding"><SectionHeader title="Decision history" description="Approval, rejection and reopen events stay attached to the exact assessment."/>{workflow.history.length?<ol className="workflow-history">{workflow.history.map(d=><li key={d.id}><strong>{d.type==="APPROVED"?"Approved":d.type==="REJECTED"?"Rejected":"Reopened"}</strong><span className="muted small"> · {new Date(d.createdAt).toLocaleString()} · decision sequence {d.sequence}</span><p className="muted small">Assessment {d.snapshotId}. {d.reviewedAt?"Explicit review: "+new Date(d.reviewedAt).toLocaleString():"Fresh review required after reopening."}</p></li>)}</ol>:<p className="muted">No human decision recorded.</p>}{workflow.historyTruncated&&<p className="muted small">Showing the latest 100 events. Earlier history remains stored.</p>}</section></>}
    <Dialog open={confirmation!==null} onClose={()=>!busy&&setConfirmation(null)} title={confirmation==="approve"?"Confirm match approval":confirmation==="reject"?"Confirm match rejection":confirmation==="reopen"?"Reopen match decision":"Archive workflow"}><p>{confirmation==="approve"?"Approve this exact reviewed pair and assessment to create local email drafts. This does not generate or send an email.":confirmation==="reject"?"Save your rejection of this exact reviewed assessment. Email drafting will remain locked.":confirmation==="reopen"?"Keep the original decision in history and clear its review and preview access. Refresh the assessment and review again before deciding.":"Archive this journey and keep its history. It will become read-only; a new workflow can be started for this source."}</p><div className="button-row"><Button variant={confirmation==="reject"?"danger":"primary"} disabled={busy} onClick={confirm}>{confirmation==="approve"?"Confirm approval":confirmation==="reject"?"Confirm rejection":confirmation==="reopen"?"Confirm reopen":"Confirm archive"}</Button><Button variant="secondary" disabled={busy} onClick={()=>setConfirmation(null)}>Cancel</Button></div></Dialog>
    <details className="preview-states"><summary>Design state examples</summary><p className="muted">Original fixed demonstrations, separate from your saved workflows.</p><WorkflowPreview/></details>
  </div>;
}
